interface UserPreferences {
  theme: string;
  language: string;
  notifications_enabled: boolean;
  last_active: string;
}

async function getUserPreferences(): Promise<UserPreferences> {
  try {
    // Fetch data from the API. 
    // The { cache: 'no-store' } option ensures the data is fetched fresh on each request.
    // In a real application, you would use an absolute URL or configure the base URL.
    const res = await fetch('http://localhost:3000/api/user/preferences', {
      cache: 'no-store',
    });

    if (!res.ok) {
      throw new Error('Failed to fetch user preferences');
    }

    return res.json();
  } catch (error) {
    console.error('Error fetching user preferences:', error);
    // Return mock data for demonstration/fallback
    return {
      theme: 'system',
      language: 'en-US',
      notifications_enabled: true,
      last_active: new Date().toISOString(),
    };
  }
}

export default async function UserDashboard() {
  const preferences = await getUserPreferences();

  return (
    <div style={{ padding: '20px', border: '1px solid #ccc', borderRadius: '8px', marginTop: '20px' }}>
      <h2>User Dashboard</h2>
      <div style={{ display: 'grid', gap: '10px' }}>
        <div>
          <strong>Theme:</strong> {preferences.theme}
        </div>
        <div>
          <strong>Language:</strong> {preferences.language}
        </div>
        <div>
          <strong>Notifications:</strong> {preferences.notifications_enabled ? 'Enabled' : 'Disabled'}
        </div>
        <div>
          <strong>Last Active:</strong> {preferences.last_active}
        </div>
      </div>
    </div>
  );
}
